SELECT * FROM join_task_result
WHERE id = #{id}
  AND status = 'PENDING'
  AND dispatch_state = 'SUBMITTED'
  AND command_id = #{commandId}
  AND attempt_no = #{attemptNo}
FOR UPDATE

mapper.update:
UPDATE join_task_result
SET dispatch_state = 'SUBMITTED', command_id = #{commandId}, attempt_no = #{attemptNo},
    next_execute_at = NULL, updated_at = #{now}
WHERE id = #{id}
  AND status = 'PENDING'
  AND dispatch_state = 'WAITING'
  AND next_execute_at IS NOT NULL
  AND next_execute_at <= #{now}

UPDATE join_task_result
SET next_execute_at = #{nextExecuteAt}, updated_at = #{now}
WHERE id = (
  SELECT id FROM (
    SELECT MIN(id) AS id
    FROM join_task_result
    WHERE join_task_id = #{joinTaskId}
      AND account_id = #{accountId}
      AND id > #{afterId}
      AND status = 'PENDING'
      AND dispatch_state = 'WAITING'
      AND next_execute_at IS NULL
  ) next_row
)
